create table public.payment_proof_legacy_backfills(id bigint generated always as identity primary key,canonical_legacy_id uuid not null,duplicate_legacy_id uuid not null unique,sha256 text not null check(sha256~'^[0-9a-f]{64}$'),canonical_payment_proof_id uuid not null references public.payment_proofs(id),duplicate_payment_proof_id uuid not null references public.payment_proofs(id),created_at timestamptz not null default now(),unique(canonical_legacy_id,duplicate_legacy_id));
revoke all on public.payment_proof_legacy_backfills from public,anon,authenticated;alter table public.payment_proof_legacy_backfills enable row level security;
create function public.apply_exact_duplicate_backfill(p_canonical_legacy_id uuid,p_duplicate_legacy_id uuid,p_sha256 text,p_canonical_proof_id uuid,p_duplicate_proof_id uuid)returns bigint language plpgsql security definer set search_path='' as $$declare r public.payment_proof_legacy_backfills%rowtype;begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception using errcode='42501',message='PAYMENT_PROOF_SERVICE_ROLE_REQUIRED';end if;if p_sha256!~'^[0-9a-f]{64}$' or p_canonical_legacy_id=p_duplicate_legacy_id then raise exception using errcode='22023',message='LEGACY_BACKFILL_INVALID';end if;select * into r from public.payment_proof_legacy_backfills where duplicate_legacy_id=p_duplicate_legacy_id;if found then if r.sha256<>p_sha256 or r.canonical_legacy_id<>p_canonical_legacy_id then raise exception using errcode='23505',message='LEGACY_BACKFILL_CONFLICT';end if;return r.id;end if;perform 1 from public.payment_proofs where id in(p_canonical_proof_id,p_duplicate_proof_id) order by id for update;insert into public.payment_proof_hash_tombstones(sha256,canonical_proof_id)values(p_sha256,p_canonical_proof_id)on conflict do nothing;update public.payment_proofs set status='admitted',sha256=p_sha256 where id=p_canonical_proof_id;update public.payment_proofs set status='quarantined',sha256=p_sha256,quarantined_at=now(),purge_after=now()+interval'10 days' where id=p_duplicate_proof_id;insert into public.payment_proof_events(proof_id,event_type,source,previous_status,result_status,metadata)values(p_canonical_proof_id,'legacy_canonical_selected','migration','received','admitted',jsonb_build_object('legacy_id',p_canonical_legacy_id)),(p_duplicate_proof_id,'legacy_duplicate_quarantined','migration','received','quarantined',jsonb_build_object('legacy_id',p_duplicate_legacy_id));insert into public.payment_proof_legacy_backfills(canonical_legacy_id,duplicate_legacy_id,sha256,canonical_payment_proof_id,duplicate_payment_proof_id)values(p_canonical_legacy_id,p_duplicate_legacy_id,p_sha256,p_canonical_proof_id,p_duplicate_proof_id)returning * into r;return r.id;end$$;revoke all on function public.apply_exact_duplicate_backfill(uuid,uuid,text,uuid,uuid)from public,anon,authenticated;grant execute on function public.apply_exact_duplicate_backfill(uuid,uuid,text,uuid,uuid)to service_role;
